#!/bin/sh

# Packages up jibo-ssm for buildroot (assumes package.json version is set) and uploads it to repository.jibo.com
# Parameter is package.json version; assumes you have cd'd into skills-service-manager directory
# $1 === version (e.g. 1.0.1)
# $2 === ldap user for uploading to repository.jibo.com

echo "\nZipping jibo-ssm...\n"
tar -czf ../jibo-ssm-$1.tar.gz  . \
    --exclude='.git' \
    --exclude='bin/utils' \
    --exclude='bin/debug-skills-service-manager-on-robot.sh' \
    --exclude='bin/run-on-robot.sh' \
    --exclude='bin/run-remote.sh' \
    --exclude='bin/start-remote.sh' \
    --exclude='node_modules/*gulp' \
    --exclude='node_modules/nugget' \
    --exclude='node_modules/extract-zip' \
    --exclude='node_modules/.bin' \
    --exclude='tests' \
    --exclude='*/node_modules/*gulp' \
    --exclude='*/node_modules/*skills-service-manager' \
    --exclude='*/node_modules/*floss' \
    --exclude='*/node_modules/*electron-prebuilt' \
    --exclude='.idea'

echo "\nSaving shasum to ../jibo-ssm-sha\n"
cd ../
shasum -a 256 jibo-ssm-$1.tar.gz > jibo-ssm-sha

echo "\nUploading to repository.jibo.com...\n"
scp jibo-ssm-$1.tar.gz $2@repository.jibo.com:/data001/www/sdk/jibo-ssm/

echo "\nDone.\n"